('Nugget Sayuran', 'nugget-sayuran', NULL, 12, 23, 'sedang', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 270, "calories_kcal": 270.5, "protein_g": 10.6, "fat_g": 15.7, "carbs_g": 21.7, "iron_mg": 1.5, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (TKPI/USDA), batas bawah"}}'::jsonb, ARRAY['150 g ubi jalar merah, rebus dan haluskan','50 g (1 butir) telur ayam, kocok','30 g daging ayam','1 cangkir bayam, cincang kasar','20 g (2 sdm) wortel, parut kasar','3 siung bawang putih, cincang','Garam secukupnya; minyak untuk menggoreng']::text[], ARRAY['telur']::text[], '[{"step": 1, "text": "Campur bayam, wortel, ubi, telur, ayam, bawang putih, dan garam hingga rata."}, {"step": 2, "text": "Bentuk pipih bulat, celupkan ke kocokan telur, lalu goreng hingga matang dan tiriskan."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 13', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', NULL),
('Nasi Ayam Katsu, Tumis Sayuran + Melon', 'nasi-ayam-katsu-tumis-sayur-melon', NULL, 24, 59, 'sedang', '1 porsi resep (lihat bahan) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 403, "calories_kcal": 403.3, "protein_g": 12.0, "fat_g": 17.7, "carbs_g": 49.0, "iron_mg": 3.7, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (TKPI/USDA), batas bawah"}}'::jsonb, ARRAY['225 g nasi putih','75 g ayam fillet','10 sdm tepung terigu','10 g tepung jagung','50 g tepung roti','1/2 butir telur ayam','30 g wortel','30 g buncis','30 g jagung pipil kuning','30 g bawang bombay','30 g bawang putih','Garam, gula, merica, air secukupnya','3 potong melon']::text[], ARRAY['gandum','telur']::text[], '[{"step": 1, "text": "Pipihkan ayam, beri garam dan merica, lapisi adonan tepung, telur, lalu tepung roti; goreng hingga kuning keemasan."}, {"step": 2, "text": "Tumis bawang, masukkan wortel, jagung, buncis, sedikit air, garam, dan gula."}, {"step": 3, "text": "Sajikan dengan nasi dan melon."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 14', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Tepung terigu tercetak ''10 sdm'' (dihitung 100 g dengan 1 sdm = 10 g). Minyak goreng tidak tercetak.'),
('Nasi Bakar Ikan Tongkol + Pepaya', 'nasi-bakar-ikan-tongkol-pepaya', NULL, 24, 59, 'ekonomis', '1 porsi resep (lihat bahan) · resep untuk 2 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 404, "calories_kcal": 403.9, "protein_g": 14.3, "fat_g": 5.8, "carbs_g": 72.3, "iron_mg": 3.0, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "estimasi dari bahan (TKPI/USDA); nilai tercetak tidak plausibel", "carbs": "estimasi dari bahan (TKPI/USDA)", "iron": "estimasi dari bahan bergramasi (TKPI/USDA), batas bawah"}}'::jsonb, ARRAY['330 g nasi putih','90 g ikan tongkol kukus','15 g bayam','45 g tahu, dihancurkan','70 ml santan','Jahe, lengkuas, serai, daun salam, kemangi, garam, gula','Bumbu halus: 2 siung bawang merah, 2 siung bawang putih, 2 butir kemiri','Daun pisang; minyak untuk menumis','Pepaya']::text[], ARRAY['ikan','kedelai']::text[], '[{"step": 1, "text": "Tumis bumbu halus dengan daun salam, serai, dan lengkuas; masukkan tongkol suwir, tahu, santan, dan bayam."}, {"step": 2, "text": "Bungkus nasi dengan daun pisang, beri isian dan kemangi."}, {"step": 3, "text": "Bakar atau kukus hingga daun kering. Sajikan dengan pepaya."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 15', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Nilai gizi tercetak identik dengan Nugget Sayuran (hlm. 13); kemungkinan salah cetak sehingga tidak dipakai. Jumlah pepaya tidak tercetak.'),
('Pepes Tahu', 'pepes-tahu', NULL, 24, 59, 'sedang', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 305, "calories_kcal": 304.7, "protein_g": 17.9, "fat_g": 17.0, "carbs_g": 20.0, "iron_mg": 6.6, "iron_coverage_pct": 97.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (TKPI/USDA), batas bawah"}}'::jsonb, ARRAY['300 g tahu putih, haluskan','100 g wortel, parut','2 siung bawang putih, 3 siung bawang merah, iris','10 g daging ayam','50 g (1 butir) telur ayam','15 g kerupuk aci','10 g daun bawang','5 g margarin','15 g (1 sdm) tepung tapioka','Daun pisang']::text[], ARRAY['kedelai','telur']::text[], '[{"step": 1, "text": "Campur tahu halus, wortel, bawang, ayam, kerupuk aci yang direndam, tapioka, dan telur kocok."}, {"step": 2, "text": "Ambil 2 sdm adonan, bungkus dengan daun pisang."}, {"step": 3, "text": "Kukus hingga matang."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 16', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', NULL),
('Omelet Mie Ceria', 'omelet-mie-ceria', NULL, 24, 59, 'sedang', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 336, "calories_kcal": 335.9, "protein_g": 15.9, "fat_g": 21.7, "carbs_g": 19.2, "iron_mg": 3.5, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (TKPI/USDA), batas bawah"}}'::jsonb, ARRAY['50 g daging ayam giling','100 g (2 butir) telur ayam','40 g sawi hijau, iris tipis','50 g tauge','10 g (1 batang) daun bawang, iris tipis','7,5 ml (1,5 sdt) kecap asin','3 g (1/2 sdt) merica','50 g wortel','20 ml (2 sdm) minyak','40 g mie kering']::text[], ARRAY['gandum','kedelai','telur']::text[], '[{"step": 1, "text": "Rebus mie hingga matang dan tiriskan, lalu aduk dengan semua bahan kecuali minyak."}, {"step": 2, "text": "Panaskan minyak di wajan antilengket, masak adonan dalam dua bagian hingga kedua sisi matang."}, {"step": 3, "text": "Potong sesuai selera dan sajikan hangat."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 17', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', NULL),
('Roti Goreng isi Ragout Ayam Sayuran', 'roti-goreng-isi-ragout-ayam-sayuran', NULL, 24, 59, 'sedang', 'Resep untuk 5 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 319, "calories_kcal": 319.2, "protein_g": 16.8, "fat_g": 12.0, "carbs_g": 36.0, "iron_mg": 1.1, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (TKPI/USDA), batas bawah"}}'::jsonb, ARRAY['300 ml susu cair','10 lembar roti tawar, potong segitiga','1/2 buah bawang bombay, cincang halus','1 sdt gula pasir, 1 sdt garam','7,5 g margarin','160 g daging ayam rebus','60 g wortel, cincang','30 g buncis, potong kecil','3 sdm tepung terigu','1 butir telur ayam','1/2 sdm seledri; tepung panir secukupnya']::text[], ARRAY['gandum','susu','telur']::text[], '[{"step": 1, "text": "Tumis bawang bombay dengan margarin, tambahkan terigu, lalu tuang susu sedikit demi sedikit sambil diaduk."}, {"step": 2, "text": "Masukkan wortel, buncis, ayam, dan bumbu hingga mengental menjadi ragout."}, {"step": 3, "text": "Olesi roti dengan susu, beri isian, tutup roti lain; celup ke telur dan tepung panir, lalu goreng."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 18', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Daging ayam tercetak dalam keadaan rebus; estimasi memakai komposisi ayam mentah sehingga cenderung rendah. Berat roti tawar tidak tercetak.'),
('Stick Ikan dan Sayur Renyah', 'stick-ikan-sayur-renyah', NULL, 24, 59, 'ekonomis', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 315, "calories_kcal": 315.2, "protein_g": 15.3, "fat_g": 19.2, "carbs_g": 20.3, "iron_mg": null, "iron_coverage_pct": 43.4, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: cakupan data bahan < 80%"}}'::jsonb, ARRAY['100 g fillet ikan segar','40 g (4 sdm) wortel','25 g kangkung','1 butir telur ayam','50 g (5 sdm) tepung bumbu serbaguna','Air es secukupnya; minyak untuk menggoreng']::text[], ARRAY['gandum','ikan','telur']::text[], '[{"step": 1, "text": "Cincang halus wortel dan kangkung, campur dengan tepung dan telur."}, {"step": 2, "text": "Tambahkan air es sedikit demi sedikit hingga adonan mengental."}, {"step": 3, "text": "Celupkan potongan fillet ikan ke adonan, goreng hingga matang."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 20', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Jenis ikan tidak disebut. Tepung bumbu serbaguna tidak ada di katalog.'),
('Ikan Bakar Balita', 'ikan-bakar-balita', NULL, 24, 59, 'ekonomis', 'Resep untuk 4 porsi', 'Lauk pendamping makan utama', '{"per": "1 porsi", "calories": 141, "calories_kcal": 140.6, "protein_g": 19.7, "fat_g": 5.6, "carbs_g": 2.8, "iron_mg": null, "iron_coverage_pct": 0.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: cakupan data bahan < 80%"}}'::jsonb, ARRAY['1 ekor ikan air tawar','2 buah jeruk nipis','Bumbu halus: 1 siung bawang putih, 5 butir bawang merah, 1/2 sdm ketumbar, 1 cm jahe, 1 cm kunyit','Garam secukupnya (boleh tidak dipakai)']::text[], ARRAY['ikan']::text[], '[{"step": 1, "text": "Lumuri ikan dengan air jeruk nipis."}, {"step": 2, "text": "Bakar di atas bara sambil dioles bumbu halus hingga matang, lalu sajikan."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 22', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Berat ikan tidak tercetak (1 ekor ikan air tawar).')
